def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    aggressive_bids = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev.get('bid', 0)
                prev_bids.append(bid)
                if bid >= 90:
                    aggressive_bids.append(bid)

    if not alive_opponents:
        return float(min(budget, 20.0))

    alive_count = len(alive_opponents)
    contested = alive_count + 1
    scarcity = supply / float(contested * WATER_REQ)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    moderate_prev = 0.0
    for b in prev_bids:
        if b < 90 and b > moderate_prev:
            moderate_prev = b

    emergency = hp <= 3 or no_water_days >= 2
    pressured = hp <= 5 or no_water_days >= 1
    tight_supply = supply <= 17
    ample_supply = supply >= 22

    if emergency:
        if aggressive_bids:
            bid = 96.0
        else:
            bid = max(62.0, moderate_prev + 2.5)
    elif tight_supply:
        if aggressive_bids and hp > 6 and no_water_days == 0:
            bid = 24.0
        else:
            bid = max(38.0, min(72.0, moderate_prev + 1.5))
    elif ample_supply and hp >= 7 and no_water_days == 0:
        if aggressive_bids:
            bid = 14.0
        else:
            bid = max(18.0, moderate_prev * 0.65 if moderate_prev > 0 else 18.0)
    elif scarcity >= 0.38 and hp >= 6:
        if aggressive_bids:
            bid = 18.0
        else:
            bid = max(22.0, moderate_prev * 0.75 if moderate_prev > 0 else 22.0)
    elif pressured:
        if aggressive_bids:
            bid = 44.0
        else:
            bid = max(48.0, moderate_prev + 2.0)
    else:
        if aggressive_bids:
            bid = 20.0
        else:
            bid = max(26.0, moderate_prev + 1.0 if moderate_prev > 0 else 26.0)

    if day >= 8 and hp >= 7 and no_water_days == 0 and not emergency:
        bid = min(bid, 24.0)

    reserve_floor = 0.0
    if hp <= 4:
        reserve_floor = 0.0
    elif day <= 3:
        reserve_floor = 140.0
    else:
        reserve_floor = 70.0

    max_affordable = budget - reserve_floor
    if max_affordable < 0:
        max_affordable = budget * 0.5

    bid = min(bid, budget, max_affordable if max_affordable > 0 else budget)
    if emergency and bid < 35.0 and budget >= 35.0:
        bid = 35.0

    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append(o)

    # If no one is alive, conserve.
    if not alive_opponents:
        bid = DAILY_SALARY * 0.4
        return max(0.0, min(my_budget, bid))

    # Read yesterday bids from previous_trace for immediate reaction.
    prev_bids = []
    for o in alive_opponents:
        prev = o.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate how competitive today is: higher supply tends to reduce scarcity,
    # but the game seems to reward aggressive bidding (Cindy/Eric).
    # Target a bid slightly under the highest observed aggressive tier.
    # Also adapt to our health.
    if my_hp <= 2.0 or my_no_water_days >= 2:
        # Need water now.
        target = min(my_budget, DAILY_SALARY * 0.95)
        # If others were bidding very high, stay near that.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            target = min(my_budget, max(target, highest_prev_bid * 0.9))
        return max(0.0, float(target))

    # If others were bidding very high yesterday, we should match the tier to avoid being outbid.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Slightly under to reduce burn while still likely winning.
        target = highest_prev_bid * 0.85
        # Adjust for supply: when supply is higher, we can bid a bit less.
        if supply >= 21.0:
            target *= 0.9
        else:
            target *= 1.0
    else:
        # Others were not extremely aggressive; bid moderate.
        target = DAILY_SALARY * 0.6
        if supply <= 18.0:
            target = DAILY_SALARY * 0.7

    # Safety cap: don't bid above what we can afford.
    target = min(my_budget, target)

    # Ensure non-negative.
    if target < 0.0:
        target = 0.0

    # Also avoid overbidding when we have plenty of HP.
    if my_hp >= 8.0 and my_no_water_days == 0:
        target = min(target, DAILY_SALARY * 0.7)

    return float(target)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return float(min(my_status['budget'], 5.0))

    yesterday_bids = [o.get('previous_trace', {}).get('bid', 0) for o in alive_opponents if o.get('previous_trace')]
    avg_opp_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 40.0

    if my_status['hp'] < 3:
        return float(min(my_status['budget'], DAILY_SALARY * 1.1))

    if supply > 20:
        bid = min(my_status['budget'], avg_opp_bid * 0.8)
    elif supply > 15:
        bid = min(my_status['budget'], avg_opp_bid * 1.05)
    else:
        bid = min(my_status['budget'], DAILY_SALARY * 0.7)

    return float(max(1.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = int(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']

    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Get yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    max_yesterday_bid = max(yesterday_bids) if yesterday_bids else 0

    # Determine urgency
    water_needed = WATER_REQ
    days_left = 10 - day + 1  # remaining days including today

    # Base bid: minimum to survive if low hp, otherwise conservative
    if hp <= 2:
        base_bid = min(budget, DAILY_SALARY * 0.9)
    elif hp <= 5:
        base_bid = min(budget, DAILY_SALARY * 0.6)
    else:
        base_bid = min(budget, DAILY_SALARY * 0.4)

    # Adjust based on supply scarcity
    if supply < water_needed * 2:
        base_bid = max(base_bid, DAILY_SALARY * 0.5)

    # Adapt to opponent behavior: outbid moderate opponents but avoid huge jumps
    if max_yesterday_bid >= DAILY_SALARY * 0.9:
        # High bidder present, conserve if possible
        if hp > 3:
            return min(budget, base_bid * 0.7)
        else:
            return min(budget, base_bid * 1.2)
    elif max_yesterday_bid >= DAILY_SALARY * 0.5:
        # Moderate pressure, slightly exceed
        target = max_yesterday_bid + 1.5
        return min(budget, max(base_bid, target))
    else:
        # Low pressure, stick to base
        return min(budget, base_bid)
